import{escapeHtml,safeUrl,filterNews}from './news-utils.mjs';
const box=document.querySelector('#latestNews');try{const r=await fetch('news.json',{cache:'no-store'});if(!r.ok)throw Error();const feed=await r.json();const items=filterNews(feed.items).slice(0,3);box.innerHTML=`<details><summary class="latest-toggle"><strong>近期材料动态</strong><span>${escapeHtml(items[0]?.title||'暂无新动态')}</span></summary>`+items.map(x=>`<a class="latest-row" href="${escapeHtml(safeUrl(x.url))}" target="_blank" rel="noopener noreferrer"><time>${escapeHtml(x.published_at)}</time><span>${escapeHtml(x.title)}</span><small>原文 ↗</small></a>`).join('')+'<a class="latest-archive" href="#news" data-view="news">查看全部动态与历史 ↗</a></details>' }catch{box.innerHTML='<a href="#news" data-view="news">查看材料动态与历史 ↗</a>'}
